mapper.select:
select por.PORTFOLIO_ID as id, por.PORTFOLIO_NAME as text from PTL_PORTFOLIO por where 1=1
AND ( por.PORTFOLIO_ID LIKE '%'||#{search}||'%' OR por.PORTFOLIO_NAME LIKE '%'||#{search}||'%' )
AND por.INVEST_YESORNO = #{investYesOrNo}
AND por.PORTFOLIO_ID = #{initValue}

SELECT DISTINCT A.STRATEGY_ID id, A.STRATEGY_NAME text FROM PTL_INV_STRATEGY A WHERE 1=1
AND (A.STRATEGY_ID like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) or A.STRATEGY_NAME like concat('%',concat(#{search,jdbcType=VARCHAR},'%')))
AND A.STRATEGY_ID = #{initValue}

select *
from PTL_PORTFOLIO_STGY 
where PORTFOLIO_ID = #{portfolioId}
and STRATEGY_ID = #{strategyId}
and EFF_DATE = DATE(#{effDate})

select count(1)
from PTL_PORTFOLIO 
where PORTFOLIO_ID = #{portfolioId}
and INVEST_YESORNO = #{investYesOrNo}
